"""Curiosities: EL2 tactical studies with reference lines and explicit traps."""
from puzzle_authoring import hero, unit, state, enchant, puzzle, cast, ability, attack, block, end

_ROLES = {
    "glass": (("The Pale Archivist", "The Sealed Alchemist"), ("Бесцветный архивариус", "Запертый алхимик")),
    "bare_echo": (("The Azure Echo", "The Iron Listener"), ("Лазурное эхо", "Железный слушатель")),
    "appetites": (("The Pale Gourmand", "The Furnace Keeper"), ("Бесцветный гурман", "Хранитель горна")),
    "borrow_door": (("The Planar Locksmith", "The White Jailer"), ("Мастер планарных замков", "Белый тюремщик")),
    "no_scratch": (("The Pale Armorer", "The Hornet Matriarch"), ("Бесцветный оружейник", "Матриарх шершней")),
    "needed_enemy": (("The Emerald Negotiator", "The Eye Keeper"), ("Изумрудный переговорщик", "Хранитель злобоглазов")),
    "late_insurance": (("The Patient Kinet", "The Ember Duelist"), ("Терпеливый кинет", "Огненный дуэлянт")),
    "lend_wings": (("The Sky Cartographer", "The Grove Warden"), ("Картограф неба", "Страж рощи")),
    "bury_tomorrow": (("The Pale Quartermaster", "The Grave Robber"), ("Бесцветный интендант", "Расхититель могильников")),
    "advance_cage": (("The Winged Strategist", "The Dragon Custodian"), ("Крылатый стратег", "Смотритель дракона")),
    "smallest_block": (("The Resonant Sentinel", "The Swarm Captain"), ("Страж резонанса", "Капитан роя")),
    "shockwave": (("The Azure Rescuer", "The Horror Tamer"), ("Лазурный спасатель", "Укротитель ужаса")),
}


def _study(slug, title, title_ru, category, category_ru, level, turns, position,
           briefing, briefing_ru, hints, hints_ru, explanation, explanation_ru,
           solution, objective=None, refutations=None):
    return puzzle("el2", "curiosity_" + slug, title, category, level, turns, position,
        briefing, hints, explanation, solution, objective=objective,
        title_ru=title_ru, category_ru=category_ru, briefing_ru=briefing_ru,
        hints_ru=hints_ru, explanation_ru=explanation_ru,
        hero_names=list(_ROLES[slug][0]),
        hero_names_ru=list(_ROLES[slug][1]),
        refutations=refutations or [])


